import React, { useEffect, useState, useMemo } from "react";
import { Container, Typography, Paper, Box, TextField, Select, MenuItem, InputLabel, FormControl, IconButton } from "@mui/material";
import { ThemeProvider, createTheme } from "@mui/material/styles";
import Brightness4Icon from "@mui/icons-material/Brightness4";
import Brightness7Icon from "@mui/icons-material/Brightness7";
import EventForm from "./components/EventForm";
import EventList from "./components/EventList";
import axios from "axios";

const API = "http://localhost:5500/api/events";

function App() {
  const [events, setEvents] = useState([]);
  const [search, setSearch] = useState("");
  const [category, setCategory] = useState("All");
  const [dark, setDark] = useState(false);
  const [editingEvent, setEditingEvent] = useState(null);

  const fetchEvents = async () => {
    const params = {};
    if (search) params.search = search;
    if (category && category !== "All") params.category = category;
    const res = await axios.get(API, { params });
    setEvents(res.data);
  };

  useEffect(() => {
    fetchEvents();
  }, [search, category]);

  const theme = useMemo(
    () => createTheme({ palette: { mode: dark ? "dark" : "light" } }),
    [dark]
  );

  return (
    <ThemeProvider theme={theme}>
      <Container maxWidth="md" sx={{ mt: 5 }}>
        <Paper sx={{ p: 3 }}>
          <Box display="flex" justifyContent="space-between" alignItems="center">
            <Typography variant="h4">🎉 College Event Manager</Typography>
            <IconButton onClick={() => setDark((d) => !d)}>
              {dark ? <Brightness7Icon /> : <Brightness4Icon />}
            </IconButton>
          </Box>

          <Box mt={2} display="flex" gap={2} alignItems="center">
            <TextField
              label="Search events"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              variant="outlined"
              size="small"
            />

            <FormControl size="small">
              <InputLabel>Category</InputLabel>
              <Select
                label="Category"
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                sx={{ minWidth: 150 }}
              >
                <MenuItem value="All">All</MenuItem>
                <MenuItem value="Technical">Technical</MenuItem>
                <MenuItem value="Cultural">Cultural</MenuItem>
                <MenuItem value="Sports">Sports</MenuItem>
                <MenuItem value="General">General</MenuItem>
              </Select>
            </FormControl>

            <Box flexGrow={1} />
            <Typography variant="body2" color="text.secondary">
              Results: {events.length}
            </Typography>
          </Box>

          <Box mt={3}>
            <EventForm onEventAdded={fetchEvents} editingEvent={editingEvent} onCancelEdit={() => setEditingEvent(null)} />
          </Box>

          <Box mt={4}>
            <EventList
              events={events}
              onDelete={async (id) => { await axios.delete(`${API}/${id}`); fetchEvents(); }}
              onEdit={(ev) => setEditingEvent(ev)}
            />
          </Box>
        </Paper>
      </Container>
    </ThemeProvider>
  );
}

export default App;
